head.script:
// 전역 변수
scwin.CURRENT_PROJECT_ID = "";
scwin.CURRENT_USER_ID = "";
scwin.CURRENT_USER_GROUP_ID = "";
scwin.MODE = ""; // "new", "edit", "view"
scwin.parentCallback = null; // 부모 창 콜백 함수

/**
 * 페이지 로드
 */
scwin.onpageload = function() {
    console.log("단위테스트 팝업 로드");

    // 부모 창에서 사용자 정보 가져오기
    scwin.getUserInfoFromParent();

    // 전달받은 데이터 처리
    scwin.processInitialData();
};

/**
 * 부모 창에서 사용자 정보 가져오기
 */
scwin.getUserInfoFromParent = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow && parentWindow.scwin) {
            scwin.CURRENT_USER_ID = parentWindow.scwin.CURRENT_USER_ID || "1";
            scwin.CURRENT_PROJECT_ID = parentWindow.scwin.CURRENT_PROJECT_ID || "";
            scwin.CURRENT_USER_GROUP_ID = parentWindow.scwin.CURRENT_USER_GROUP_ID || "2";

            console.log("부모 창에서 사용자 정보 가져옴:", {
                userId: scwin.CURRENT_USER_ID,
                projectId: scwin.CURRENT_PROJECT_ID,
                groupId: scwin.CURRENT_USER_GROUP_ID
            });
        }
    } catch (e) {
        console.error("부모 창에서 사용자 정보 가져오기 실패:", e);
        scwin.CURRENT_USER_ID = "1";
        scwin.CURRENT_PROJECT_ID = "";
        scwin.CURRENT_USER_GROUP_ID = "2";
    }
};

/**
 * 초기 데이터 처리
 */
scwin.processInitialData = function() {
    try {
        var popupData = $p.getParameter("popupData");
        console.log("팝업 전달 데이터:", popupData);

        if (popupData) {
            scwin.MODE = popupData.mode || "new";
            scwin.parentCallback = popupData.callback;

            if (popupData.testData) {
                // 기존 데이터가 있으면 설정
                dmp_unitTestDetail.setJSON(popupData.testData);
                scwin.loadFileList();
            } else {
                // 새 등록인 경우 기본값 설정
                scwin.initializeNewTest(popupData);
            }

            // 모드에 따른 UI 설정
            scwin.setFormMode(scwin.MODE);
            scwin.updateTitle();
        }
    } catch (e) {
        console.error("초기 데이터 처리 실패:", e);
        scwin.MODE = "new";
        scwin.setFormMode("new");
    }
};

/**
 * 새 테스트 케이스 초기화
 */
scwin.initializeNewTest = function(popupData) {
    dmp_unitTestDetail.setEmptyValue();

    // 기본값 설정
    dmp_unitTestDetail.set("testCaseId", "");
    dmp_unitTestDetail.set("testStatus", "SUC");
    dmp_unitTestDetail.set("priority", "MEDIUM");
    dmp_unitTestDetail.set("testType", "NORMAL");
    dmp_unitTestDetail.set("assignee", scwin.CURRENT_USER_ID);
    dmp_unitTestDetail.set("assigneeName", scwin.getCurrentUserName() || "현재 사용자");

    if (scwin.CURRENT_PROJECT_ID) {
        dmp_unitTestDetail.set("pjtId", scwin.CURRENT_PROJECT_ID);
    }

    // 개발업무에서 전달받은 데이터가 있으면 설정
    if (popupData && popupData.taskId) {
        dmp_unitTestDetail.set("taskId", popupData.taskId);
        dmp_unitTestDetail.set("taskName", popupData.taskName || "");
    }

    // 파일 관련 초기화
    dlt_upload.setJSON([]);
    dlt_attVoList.setJSON([]);

    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

/**
 * 제목 업데이트
 */
scwin.updateTitle = function() {
    var title = "";
    switch(scwin.MODE) {
        case "new":
            title = "새 단위테스트 케이스 등록";
            break;
        case "edit":
            title = "단위테스트 케이스 수정";
            break;
        case "view":
            title = "단위테스트 케이스 상세정보";
            break;
        default:
            title = "단위테스트 케이스 관리";
    }

    try {
        spn_popupTitle.setValue(title);
    } catch(e) {
        setTimeout(function() {
            try {
                spn_popupTitle.setValue(title);
            } catch(e2) {
                console.error("제목 설정 실패:", e2);
            }
        }, 100);
    }
};

/**
 * 폼 모드 설정 (외부에서 호출 가능)
 */
scwin.setFormMode = function(mode) {
    console.log("폼 모드 전환:", mode);
    scwin.MODE = mode;

    if (mode === "edit" || mode === "new") {
        // 편집/등록 모드
        scwin.setFieldsReadOnly(false);
        scwin.setEditorMode(true);
        scwin.showFileUploadSection(true);

        // 버튼 상태
        btn_save.show();
        btn_edit.hide();
        btn_delete.hide();

    } else if (mode === "view") {
        // 조회 모드
        scwin.setFieldsReadOnly(true);
        scwin.setEditorMode(false);
        scwin.showFileUploadSection(false);

        // 버튼 상태
        btn_save.hide();
        btn_edit.show();
        btn_delete.show();
    }

    scwin.updateTitle();
};

/**
 * 데이터 로드 (외부에서 호출 가능)
 */
scwin.loadData = function(testData) {
    if (testData) {
        dmp_unitTestDetail.setJSON(testData);
        scwin.loadFileList();
    }
};

/**
 * 폼 데이터 반환 (외부에서 호출 가능)
 */
scwin.getFormData = function() {
    return dmp_unitTestDetail.getJSON();
};

/**
 * 필드 읽기 전용 설정
 */
scwin.setFieldsReadOnly = function(readOnly) {
    try {
        var editableFields = [
            "inp_testCaseName",
            "inp_testTarget", 
            "sel_testType",
            "sel_priority",
            "sel_testStatus",
            "cal_executionDate",
            "inp_duration"
        ];

        editableFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(readOnly);
            }
        });

        // 업무명과 담당자명은 항상 readOnly
        var alwaysReadOnlyFields = ["inp_taskName", "inp_assignee"];
        alwaysReadOnlyFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(true);
            }
        });

    } catch(e) {
        console.error("필드 읽기 전용 설정 오류:", e);
    }
};

/**
 * 에디터 모드 설정
 */
scwin.setEditorMode = function(isEditMode) {
    console.log("에디터 모드 전환:", isEditMode ? "편집" : "조회");

    if (isEditMode) {
        // 편집 모드: 에디터 표시
        grp_description_edit.show();
        grp_description_view.hide();
        grp_testData_edit.show();
        grp_testData_view.hide();
    } else {
        // 조회 모드: 읽기 전용 표시
        grp_description_edit.hide();
        grp_description_view.show();
        grp_testData_edit.hide();
        grp_testData_view.show();

        // 내용 업데이트
        scwin.updateViewContent();
    }
};

/**
 * 파일 업로드 섹션 표시
 */
scwin.showFileUploadSection = function(show) {
    try {
        if (show) {
            grp_fileUploadArea.show();
        } else {
            grp_fileUploadArea.hide();
        }
    } catch(e) {
        console.error("파일 업로드 섹션 표시 오류:", e);
    }
};

/**
 * 조회 모드 내용 업데이트
 */
scwin.updateViewContent = function() {
    try {
        var description = dmp_unitTestDetail.get("description") || "";
        var testData = dmp_unitTestDetail.get("testData") || "";

        // HTML 태그 제거
        txt_description_view.setValue(scwin.stripHtmlTags(description));
        txt_testData_view.setValue(scwin.stripHtmlTags(testData));

    } catch(e) {
        console.error("내용 업데이트 실패:", e);
    }
};

/**
 * HTML 태그 제거
 */
scwin.stripHtmlTags = function(htmlString) {
    if (!htmlString) return "";

    var text = htmlString.replace(/<[^>]*>/g, "");
    text = text.replace(/&nbsp;/g, " ");
    text = text.replace(/&lt;/g, "<");
    text = text.replace(/&gt;/g, ">");
    text = text.replace(/&amp;/g, "&");
    text = text.replace(/&quot;/g, '"');
    text = text.replace(/\s+/g, " ").trim();

    return text;
};

/**
 * 업무 선택 버튼 클릭
 */
scwin.btn_selectTask_onclick = function(e) {
    console.log("업무 선택 버튼 클릭");

    var currentTaskData = dmp_unitTestDetail.getJSON();

    var taskData = {
        currentTaskId: currentTaskData.taskId,
        currentTaskName: currentTaskData.taskName,
        currentPjtId: scwin.CURRENT_PROJECT_ID
    };

    var jsnPopupData = {
        "type": "json",
        "name": "taskData",
        "data": taskData
    };

    var options = {
        id: "task_tree_popup_test",
        type: "wframePopup", 
        width: "600px",
        height: "650px",
        top: "30px",
        left: "300px",
        popupName: "업무 선택",
        modal: true,
        closeAction: "scwin.taskTreePopup_closeAction",
        dataObject: jsnPopupData
    };

    $p.openPopup("/InsWebApp/ui/task/allTask/AllTaskTree.xml", options);
};

/**
 * 업무 트리 팝업에서 데이터 받기
 */
scwin.receiveTaskData = function(returnData) {
    if (returnData && returnData.selectedTask) {
        var selectedTask = returnData.selectedTask;

        dmp_unitTestDetail.set("taskId", selectedTask.taskId);
        dmp_unitTestDetail.set("taskName", selectedTask.taskName);

        console.log("선택된 업무:", selectedTask.taskName);
        //$c.win.alert("선택된 업무: " + selectedTask.taskName);
    }
};

/**
 * 업무 트리 팝업 닫기 콜백
 */
scwin.taskTreePopup_closeAction = function() {
    return true;
};

/**
 * 업무명 초기화
 */
scwin.btn_resetTask_onclick = function(e) {
    dmp_unitTestDetail.set("taskId", "");
    dmp_unitTestDetail.set("taskName", "");
    $c.win.alert("업무 선택이 초기화되었습니다.");
};

/**
 * 저장 버튼 클릭
 */
scwin.btn_save_onclick = function(e) {
    console.log("저장 버튼 클릭");

    // 수정 권한 체크 (수정 모드인 경우)
    if (scwin.MODE === "edit" && !scwin.checkEditPermission()) {
        $c.win.alert("본인이 담당한 테스트만 수정할 수 있습니다.");
        return;
    }

    // 유효성 검사
    if (!scwin.validateForm()) {
        return;
    }

    // 파일이 있는지 확인
    var hasFiles = false;
    if (mpd_html5Type && mpd_html5Type.fileArray) {
        hasFiles = mpd_html5Type.fileArray.length > 0;
    }

    if (hasFiles) {
        // 파일과 함께 저장
        scwin.saveTestWithFiles();
    } else {
        // 일반 저장
        if (scwin.MODE === "new") {
            sbm_saveUnitTest.setAction("/InsWebApp/UNIT001Ins.pwkjson");
        } else {
            sbm_saveUnitTest.setAction("/InsWebApp/UNIT001Upd.pwkjson");
        }
        $c.sbm.execute($p, sbm_saveUnitTest);
    }
};

/**
 * 수정 권한 확인
 */
scwin.checkEditPermission = function() {
    // PM이면 모든 테스트 수정 가능
    if (String(scwin.CURRENT_USER_GROUP_ID) === "1") {
        return true;
    }

    // 일반 사용자는 자신이 담당한 테스트만 수정 가능
    var assignee = dmp_unitTestDetail.get("assignee");
    return assignee === scwin.CURRENT_USER_ID;
};

/**
 * 폼 유효성 검사
 */
scwin.validateForm = function() {
    var testCaseName = dmp_unitTestDetail.get("testCaseName");
    var testTarget = dmp_unitTestDetail.get("testTarget");
    var taskId = dmp_unitTestDetail.get("taskId");
    var taskName = dmp_unitTestDetail.get("taskName");

    if (!taskId || taskId.trim() === "" || !taskName || taskName.trim() === "") {
        $c.win.alert("업무를 선택해주세요.");
        return false;
    }

    if (!testCaseName || testCaseName.trim() === "") {
        $c.win.alert("테스트케이스명을 입력해주세요.");
        return false;
    }

    if (!testTarget || testTarget.trim() === "") {
        $c.win.alert("테스트 대상을 입력해주세요.");
        return false;
    }

    return true;
};

/**
 * 파일과 함께 저장
 */
scwin.saveTestWithFiles = function() {
    console.log("=== 파일과 함께 저장 시작 ===");

    // 에디터 포커스 해제하여 내용 확정
    try {
        if (editor_description && editor_description.blur) {
            editor_description.blur();
        }
        if (editor_testData && editor_testData.blur) {
            editor_testData.blur();
        }
    } catch(e) {
        console.log("에디터 blur 실패, 무시");
    }

    // 잠시 대기 후 저장 실행
    setTimeout(function() {
        scwin.executeFileUploadWithData();
    }, 100);
};

/**
 * 실제 파일 업로드와 데이터 전송 실행
 */
scwin.executeFileUploadWithData = function() {
    console.log("executeFileUploadWithData() 시작됨");

    // 에디터 내용 동기화
    try {
        var descriptionHTML = "";
        var testDataHTML = "";

        if (editor_description && typeof editor_description.getHTML === 'function') {
            descriptionHTML = editor_description.getHTML();
        }

        if (editor_testData && typeof editor_testData.getHTML === 'function') {
            testDataHTML = editor_testData.getHTML();
        }

        dmp_unitTestDetail.set("description", descriptionHTML);
        dmp_unitTestDetail.set("testData", testDataHTML);

    } catch(e) {
        console.error("에디터 내용 가져오기 실패:", e);
    }

    // FormData 생성
    var formData = new FormData();

    // 테스트 케이스 데이터 추가
    var testData = dmp_unitTestDetail.getJSON();
    Object.keys(testData).forEach(function(key) {
        formData.append(key, testData[key] || "");
    });

    // 파일 추가
    var hasValidFiles = false;
    if (mpd_html5Type && mpd_html5Type.fileArray) {
        var fileList = mpd_html5Type.fileArray;
        if (fileList && fileList.length > 0) {
            for (var i = 0; i < fileList.length; i++) {
                var fileItem = fileList[i];
                var realFile = fileItem.file || fileItem;

                if (realFile && realFile instanceof File && realFile.size > 0) {
                    formData.append("files", realFile);
                    hasValidFiles = true;
                }
            }
        }
    }

    // 서버 URL 결정
    var actionUrl = scwin.MODE === "new" ? 
        "/InsWebApp/UNIT001InsWithFiles.pwkjson" : 
        "/InsWebApp/UNIT001UpdWithFiles.pwkjson";

    // 서버로 전송
    fetch(actionUrl, {
        method: "POST",
        body: formData
    })
    .then(function(res) { 
        if (!res.ok) {
            throw new Error('HTTP ' + res.status + ': ' + res.statusText);
        }
        return res.json(); 
    })
    .then(function(res) {
        console.log("서버 응답:", res);

        var elHeader = res.elHeader;

        if (elHeader && elHeader.resSuc === true) {
            $c.win.alert(scwin.MODE === "new" ? "등록되었습니다." : "수정되었습니다.");

            // 파일 목록 초기화
            dlt_upload.setJSON([]);
            if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
                mpd_html5Type.removeAllFiles();
            }

            // 부모 창에 결과 전달 후 팝업 닫기
            scwin.closePopupWithCallback(true);

        } else {
            var errorMsg = (scwin.MODE === "new" ? "등록" : "수정") + "에 실패했습니다.";
            if (elHeader && elHeader.resMsg) {
                errorMsg += "\n오류메시지: " + elHeader.resMsg;
            }
            $c.win.alert(errorMsg);
        }
    })
    .catch(function(err) {
        console.error("전송 실패:", err);
        $c.win.alert((scwin.MODE === "new" ? "등록" : "수정") + " 중 오류가 발생했습니다.");
    });
};

/**
 * 저장 완료
 */
scwin.sbm_saveUnitTest_submitdone = function(e) {
    console.log("저장 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
        return;
    }

    $c.win.alert(scwin.MODE === "new" ? "등록되었습니다." : "수정되었습니다.");
    scwin.closePopupWithCallback(true);
};

/**
 * 수정 버튼 클릭
 */
scwin.btn_edit_onclick = function(e) {
    console.log("수정 버튼 클릭");

    if (!scwin.checkEditPermission()) {
        $c.win.alert("본인이 담당한 테스트만 수정할 수 있습니다.");
        return;
    }

    scwin.setFormMode("edit");
};

/**
 * 삭제 버튼 클릭
 */
scwin.btn_delete_onclick = function(e) {
    console.log("삭제 버튼 클릭");

    if (!scwin.checkEditPermission()) {
        $c.win.alert("본인이 담당한 테스트만 삭제할 수 있습니다.");
        return;
    }

    var testCaseId = dmp_unitTestDetail.get("testCaseId");

    if (!testCaseId) {
        $c.win.alert("삭제할 테스트 케이스를 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("삭제하시겠습니까?\n관련된 파일도 함께 삭제됩니다.");
    promise.then(function(result) {
        if (result) {
            $c.sbm.execute($p, sbm_deleteUnitTest);
        }
    });
};

/**
 * 삭제 완료
 */
scwin.sbm_deleteUnitTest_submitdone = function(e) {
    console.log("삭제 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
        return;
    }

    $c.win.alert("삭제되었습니다.");
    scwin.closePopupWithCallback(true);
};

/**
 * 초기화 버튼 클릭
 */
scwin.btn_reset_onclick = function(e) {
    console.log("초기화 버튼 클릭");

    if (scwin.MODE === "new") {
        // 새 등록 모드에서만 초기화 가능
        scwin.initializeNewTest();
        scwin.hideAllPreviewPanels();
        scwin.showNoPreview();
    } else {
        $c.win.alert("조회/수정 모드에서는 초기화할 수 없습니다.");
    }
};

/**
 * 닫기 버튼 클릭
 */
scwin.btn_close_onclick = function(e) {
    console.log("팝업 닫기");
    scwin.closePopupWithCallback(false);
};

/**
 * 팝업 닫기 (콜백 포함)
 */
scwin.closePopupWithCallback = function(isSuccess) {
    try {
        // 부모 창에 결과 전달
        if (scwin.parentCallback && typeof scwin.parentCallback === 'function') {
            scwin.parentCallback(isSuccess);
        }
    } catch(e) {
        console.error("부모 콜백 실행 실패:", e);
    }

    // 팝업 닫기
    $p.closePopup();
};

/**
 * 현재 사용자 이름 가져오기
 */
scwin.getCurrentUserName = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow && parentWindow.scwin && parentWindow.scwin.getCurrentUserName) {
            return parentWindow.scwin.getCurrentUserName();
        }
        return "사용자";
    } catch (e) {
        console.error("사용자 이름 가져오기 실패:", e);
        return "사용자";
    }
};

// === 파일 관련 기능들 ===

/**
 * 파일 선택 완료 콜백
 */
scwin.multiUploadSelectDone = function() {
    console.log("=== 파일 선택 완료 콜백 실행 ===");

    var fileInfos = mpd_html5Type.getFileInfos();
    var newFileData = [];

    if (fileInfos && fileInfos.length > 0) {
        for (var i = 0; i < fileInfos.length; i++) {
            var file = fileInfos[i];
            newFileData.push({
                originalFileName: file.name,
                fileSize: file.size,
                fileExtension: scwin.getFileExtension(file.name),
                status: "업로드 대기"
            });
        }
    }

    dlt_upload.setJSON(newFileData);
    console.log("업로드 대기 파일 수:", newFileData.length);
};

/**
 * 파일 확장자 추출
 */
scwin.getFileExtension = function(fileName) {
    if (!fileName || fileName.indexOf('.') === -1) return '';
    return fileName.split('.').pop().toLowerCase();
};

/**
 * 파일 목록 로드
 */
scwin.loadFileList = function() {
    console.log("=== 파일 목록 로드 시작 ===");

    var testCaseId = dmp_unitTestDetail.get("testCaseId");
    console.log("테스트 케이스 ID:", testCaseId);

    if (!testCaseId || testCaseId.trim() === "") {
        console.log("테스트 케이스 ID가 없습니다. 파일 목록을 초기화합니다.");
        dlt_attVoList.setJSON([]);
        scwin.hideAllPreviewPanels();
        scwin.showNoPreview();
        return;
    }

    $c.sbm.execute($p, sbm_selectUnitTestFileList);
};

/**
 * 파일 목록 조회 완료
 */
scwin.sbm_selectUnitTestFileList_submitdone = function(e) {
    console.log("=== 파일 목록 조회 응답 처리 시작 ===");

    try {
        var responseData = e.responseJSON;
        var elData = responseData ? responseData.elData : null;
        var elHeader = responseData ? responseData.elHeader : null;

        if (!elHeader || elHeader.resSuc !== true) {
            console.error("파일 목록 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
            dlt_attVoList.setJSON([]);
            return;
        }

        var fileList = [];
        if (elData && elData.attVoList) {
            fileList = elData.attVoList;
        }

        dlt_attVoList.setJSON(fileList);
        console.log("파일 목록 설정 완료:", fileList.length, "개");

        if (fileList.length === 0) {
            scwin.hideAllPreviewPanels();
            scwin.showNoPreview();
        }

    } catch (error) {
        console.error("응답 처리 중 오류:", error);
        dlt_attVoList.setJSON([]);
    }
};

/**
 * 파일 목록 조회 실패 콜백
 */
scwin.sbm_selectUnitTestFileList_submiterror = function(e) {
    console.error("파일 목록 조회 실패:", e);
    dlt_attVoList.setJSON([]);
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

/**
 * 파일 그리드 셀 클릭 (미리보기)
 */
scwin.grd_fileList_oncellclick = function(row, col, colId) {
    console.log("파일 그리드 셀 클릭:", row, colId);

    var rowData = dlt_attVoList.getRowJSON(row);

    if (colId === "originalFileName") {
        scwin.previewFile(rowData.fileId, rowData.originalFileName, rowData.fileExtension);
    }
};

/**
 * 파일 그리드 액션 버튼 클릭
 */
scwin.fileActionClick = function(row, col, colId, targetId) {
    console.log("파일 액션 클릭:", row, targetId);

    var rowData = dlt_attVoList.getRowJSON(row);
    var fileId = rowData.fileId;
    var fileName = rowData.originalFileName;

    if (!fileId) {
        alert("파일 ID가 없습니다.");
        return;
    }

    if (targetId && (targetId.indexOf("download") >= 0 || targetId.indexOf("다운로드") >= 0)) {
        scwin.downloadFile(fileId, fileName);
    } else if (col === 3) {
        scwin.downloadFile(fileId, fileName);
    } else if (targetId && (targetId.indexOf("delete") >= 0 || targetId.indexOf("삭제") >= 0)) {
        scwin.deleteFile(fileId);
    } else {
        scwin.downloadFile(fileId, fileName);
    }
};

/**
 * 파일 미리보기
 */
scwin.previewFile = function(fileId, fileName, fileExtension) {
    console.log("파일 미리보기:", fileName, fileExtension);

    dmp_currentFile.set("fileId", fileId);
    dmp_currentFile.set("originalFileName", fileName);
    dmp_currentFile.set("fileExtension", fileExtension);

    scwin.hideAllPreviewPanels();

    var ext = fileExtension ? fileExtension.toLowerCase() : "";

    if (scwin.isImageFile(ext)) {
        scwin.showImagePreview(fileId, fileName);
    } else if (scwin.isTextFile(ext)) {
        scwin.showTextPreview(fileId, fileName);
    } else if (scwin.isDocumentFile(ext)) {
        scwin.showDocumentPreview(fileId, fileName, ext);
    } else {
        scwin.showUnsupportedPreview(fileName);
    }
};

/**
 * 파일 타입 체크
 */
scwin.isImageFile = function(ext) {
    var imageExts = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'svg', 'webp'];
    return imageExts.indexOf(ext) !== -1;
};

scwin.isTextFile = function(ext) {
    var textExts = ['txt', 'log', 'csv', 'json', 'xml', 'html', 'css', 'js', 'java', 'sql', 'properties'];
    return textExts.indexOf(ext) !== -1;
};

scwin.isDocumentFile = function(ext) {
    var docExts = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'hwp'];
    return docExts.indexOf(ext) !== -1;
};

/**
 * 미리보기 패널 제어
 */
scwin.hideAllPreviewPanels = function() {
    try {
        grp_noPreview.hide();
        grp_imagePreview.hide();
        grp_textPreview.hide();
        grp_documentPreview.hide();
    } catch(e) {
        console.error("미리보기 패널 숨기기 오류:", e);
    }
};

scwin.showNoPreview = function() {
    try {
        grp_noPreview.show();
    } catch(e) {
        console.error("기본 미리보기 표시 오류:", e);
    }
};

scwin.showImagePreview = function(fileId, fileName) {
    console.log("이미지 미리보기:", fileName);

    var imageUrl = "/InsWebApp/ImagePreview.pwkjson?fileId=" + fileId;

    try {
        txt_previewFileName.setValue(fileName);
        grp_imagePreview.show();

        setTimeout(function() {
            var imgElement = document.getElementById("img_preview");
            if (imgElement) {
                imgElement.src = imageUrl;
                imgElement.style.width = "150px";
                imgElement.style.height = "150px";
                imgElement.style.objectFit = "cover";
                imgElement.style.border = "1px solid #ddd";
                imgElement.style.background = "white";
                imgElement.style.boxShadow = "0 2px 8px rgba(0,0,0,0.1)";
                imgElement.style.borderRadius = "4px";

                imgElement.onerror = function() {
                    console.error("이미지 로드 실패:", imageUrl);
                    scwin.showUnsupportedPreview(fileName, "이미지를 로드할 수 없습니다.");
                };
            }
        }, 100);
    } catch(e) {
        console.error("이미지 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

scwin.showTextPreview = function(fileId, fileName) {
    console.log("텍스트 미리보기:", fileName);

    try {
        txt_textFileName.setValue(fileName);
        grp_textPreview.show();

        fetch("/InsWebApp/FilePreview.pwkjson?fileId=" + fileId)
            .then(function(response) { return response.text(); })
            .then(function(text) {
                if (text.length > 5000) {
                    text = text.substring(0, 5000) + "\n\n... (파일 내용이 길어서 일부만 표시됩니다)";
                }
                txt_textContent.setValue(text);
            })
            .catch(function(error) {
                console.error("텍스트 파일 로드 실패:", error);
                txt_textContent.setValue("텍스트 파일을 로드할 수 없습니다.");
            });
    } catch(e) {
        console.error("텍스트 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

scwin.showDocumentPreview = function(fileId, fileName, ext) {
    console.log("문서 미리보기:", fileName, ext);

    try {
        txt_documentFileName.setValue(fileName);

        var fileInfo = "";
        switch(ext) {
            case 'pdf': fileInfo = "PDF 문서 파일입니다."; break;
            case 'doc':
            case 'docx': fileInfo = "Microsoft Word 문서입니다."; break;
            case 'xls':
            case 'xlsx': fileInfo = "Microsoft Excel 스프레드시트입니다."; break;
            case 'ppt':
            case 'pptx': fileInfo = "Microsoft PowerPoint 프레젠테이션입니다."; break;
            case 'hwp': fileInfo = "한글 문서 파일입니다."; break;
            default: fileInfo = "문서 파일입니다.";
        }

        txt_documentInfo.setValue(fileInfo);
        grp_documentPreview.show();
    } catch(e) {
        console.error("문서 미리보기 오류:", e);
        scwin.showUnsupportedPreview(fileName);
    }
};

scwin.showUnsupportedPreview = function(fileName, message) {
    console.log("지원하지 않는 파일 미리보기:", fileName);
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

/**
 * 현재 미리보기 파일 다운로드
 */
scwin.downloadCurrentFile = function() {
    var fileId = dmp_currentFile.get("fileId");
    var fileName = dmp_currentFile.get("originalFileName");

    if (fileId && fileName) {
        scwin.downloadFile(fileId, fileName);
    } else {
        alert("다운로드할 파일 정보가 없습니다.");
    }
};

/**
 * 파일 다운로드
 */
scwin.downloadFile = function(fileId, fileName) {
    console.log("파일 다운로드:", fileName, "ID:", fileId);

    if (!fileId || !fileName) {
        alert("다운로드할 파일 정보가 없습니다.");
        return;
    }

    try {
        var downloadUrl = "/InsWebApp/FileDownload.pwkjson?fileId=" + encodeURIComponent(fileId);

        var iframe = document.createElement('iframe');
        iframe.style.display = 'none';
        iframe.style.position = 'absolute';
        iframe.style.left = '-9999px';
        iframe.src = downloadUrl;

        document.body.appendChild(iframe);

        setTimeout(function() {
            if (iframe.parentNode) {
                document.body.removeChild(iframe);
            }
        }, 3000);

        console.log("파일 다운로드 요청 완료");

    } catch (error) {
        console.error("파일 다운로드 실패:", error);
        alert("파일 다운로드 중 오류가 발생했습니다: " + error.message);
    }
};

/**
 * 파일 삭제
 */
scwin.deleteFile = function(fileId) {
    console.log("파일 삭제:", fileId);

    if (!fileId) {
        alert("삭제할 파일을 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("파일을 삭제하시겠습니까?");
    promise.then(function(result) {
        if (result) {
            dmp_currentFile.set("fileId", fileId);
            $c.sbm.execute($p, sbm_deleteUnitTestFile);
        }
    });
};

scwin.sbm_deleteUnitTestFile_submit = function(e) {
    var fileId = dmp_currentFile.get("fileId");
    if (!fileId) {
        console.error("삭제할 파일 ID가 없습니다.");
        return;
    }

    var deleteUrl = "/InsWebApp/UNIT001FileDelete.pwkjson?fileId=" + encodeURIComponent(fileId);
    sbm_deleteUnitTestFile.setAction(deleteUrl);
    sbm_deleteUnitTestFile.setRequestData("");
};

/**
 * 파일 삭제 완료
 */
scwin.sbm_deleteUnitTestFile_submitdone = function(e) {
    console.log("파일 삭제 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        alert("파일 삭제 실패: " + (elHeader ? elHeader.resMsg : "알 수 없는 오류"));
        return;
    }

    alert("파일이 삭제되었습니다.");

    var deletedFileId = dmp_currentFile.get("fileId");
    if (deletedFileId) {
        scwin.hideAllPreviewPanels();
        scwin.showNoPreview();
        dmp_currentFile.setEmptyValue();
    }

    scwin.loadFileList();
};

/**
 * 파일 업로드 초기화
 */
scwin.btn_InitMultiupload_onclick = function(e) {
    console.log("파일 업로드 초기화");

    dlt_upload.setJSON([]);

    if (mpd_html5Type) {
        if (mpd_html5Type.clear) {
            mpd_html5Type.clear();
        } else if (mpd_html5Type.removeAllFiles) {
            mpd_html5Type.removeAllFiles();
        } else if (mpd_html5Type.fileArray) {
            mpd_html5Type.fileArray = [];
        }
    }

    console.log("파일 업로드 초기화 완료");
};

/**
 * 업로드 파일 삭제
 */
scwin.removeUploadFile = function(row, col, colId, targetId) {
    console.log("업로드 파일 삭제:", row);

    try {
        dlt_upload.removeRow(row);

        if (mpd_html5Type && mpd_html5Type.removeFileByIndex) {
            mpd_html5Type.removeFileByIndex(row);
        } else if (mpd_html5Type && mpd_html5Type.fileArray) {
            mpd_html5Type.fileArray.splice(row, 1);
        }

        try {
            grd_uploadList.refresh();
        } catch(e) {
            console.log("그리드 새로고침 실패, 무시");
        }

    } catch(error) {
        console.error("파일 삭제 중 오류:", error);
        alert("파일 삭제 중 오류가 발생했습니다.");
    }
};
